/* ─────────────────────────────────────────────────────────────
 * 차팅 용어 — 한국어 임상 표현 → 영어 차팅 표현
 *
 * SOAP의 O(소견)와 A(진단·판정)에 쓰는 어휘만 수록한다.
 * 술식·재료·기구·설계 용어(Tx·P 어휘)는 여기에 넣지 않는다.
 * 목적은 번역이 아니라 "어느 단어를 골라야 하는가"의 감별.
 * 한 표현이 대상·원인에 따라 다른 영어 단어가 되는 지점을 중심으로 정리한다.
 *
 * section 태그
 *   O  — 관찰·기술 용어. 진단이 아님
 *   A  — 진단·판정 용어
 *   O·A — 맥락에 따라 양쪽
 *
 * 각 항목
 * 참고 교과서
 *   구강내과 — Burket's Oral Medicine / Neville, Oral and Maxillofacial Pathology
 *              Scully, Oral and Maxillofacial Medicine / Okeson, Management of TMD
 *   보철과   — GPT-10 (용어 기준) / Shillingburg / Rosenstiel / McCracken
 *              Zarb·Boucher, Prosthodontic Treatment for Edentulous Patients / Misch
 *   치주     — Newman & Carranza / Lindhe / 2017 World Workshop
 *   구강외과 — Hupp·Peterson, Contemporary Oral and Maxillofacial Surgery / Fragiskos
 *   근관     — Cohen's Pathways of the Pulp / Ingle's Endodontics
 *   교정     — Proffit, Contemporary Orthodontics
 *   수복     — Sturdevant's Art and Science of Operative Dentistry
 *   방사선   — White & Pharoah, Oral Radiology
 *   마취     — Malamed, Handbook of Local Anesthesia
 *
 *   meaning  — 무엇을 가리키는가
 *   variants — 갈리는 지점(대상·원인별로 다른 단어)
 *   example  — 실제 차팅 문장
 *   caution  — 혼동·오용 주의
 * ───────────────────────────────────────────────────────────── */

