    distinguish: "- **suggestive of** — 가리키는 정도(더 약함)\n- **consistent with** — 부합함(더 강하나 확진은 아님)\n- **diagnostic of / confirmed** — 확진. 병리·검사 결과가 있을 때만 쓴다",
