    distinguish: "- **일정한 압력**(약 1 kg, 2초)으로 좌우를 비교해야 의미가 있다\n- **familiar pain 여부**가 핵심 — 그냥 아픈 것과 평소 통증이 재현되는 것은 다른 소견이다\n- **연관통이 동반**되면 근막통 쪽을 강하게 시사",
