    meaning: "**구개 융기** — 경구개 정중부의 골성 융기. **하악 융기** — 하악 설측 소구치 부위의 골성 융기로 대개 양측성이다. 둘 다 정상 변이이며 서서히 커지고, 표면 점막이 얇아 궤양이 생기기 쉽다.",
