    meaning: "항흡수제·항혈관형성제 투여력이 있고 **방사선 조사력이 없는** 환자에서, 악골이 노출되거나 누공을 통해 골이 탐침되는 상태가 **8주 이상 지속**되는 것. 하악 후방에 호발한다.",
    variants: "<dl><dt>Stage 0</dt><dd>노출 골 없이 비특이 증상·영상 소견</dd><dt>Stage 1</dt><dd>노출 골, <b>무증상·감염 없음</b></dd><dt>Stage 2</dt><dd>노출 골 + <b>통증·감염</b></dd><dt>Stage 3</dt><dd>치조골을 넘는 확장 — 병적 골절, 구외 누공, 상악동 교통 등</dd></dl>",
