    variants: "<dl><dt>Class I</dt><dd>정상 구치 관계</dd><dt>Class II div 1</dt><dd>원심교합 + <b>상악 전치 순측 경사</b>(overjet 증가)</dd><dt>Class II div 2</dt><dd>원심교합 + <b>상악 중절치 설측 경사</b>, 깊은 수직피개</dd><dt>Class III</dt><dd>근심교합</dd></dl>",
    distinguish: "- **골격 분류와 다르다** — Class II 치아 관계라도 골격은 Class I일 수 있다. **ANB 등 계측을 함께** 적어야 진단이 완성된다\n- **div 1과 div 2는 상악 절치 경사로 갈린다** — 치료 방향이 완전히 다르다\n- 제1대구치가 없거나 이동했으면 **견치 관계로 보완**해 기술",
