    distinguish: "- **좌우를 각각 적는다** — 편측만 Class II인 경우가 흔하다\n- **구치 관계와 불일치**하면 그 자체가 정보다 — 치아 이동·비대칭을 시사\n- 보철에서는 견치 관계가 **측방 유도 설계**에 직접 영향을 준다",
