    distinguish: "- **Angle 분류(치아)와 반드시 함께** 적는다 — 둘이 불일치하는 경우가 흔하고, 그 불일치가 치료 계획을 정한다\n- **ANB만 보면 오도될 수 있다** — S-N 평면 자체가 기울면 값이 왜곡되므로 Wits 등 보조 계측으로 교차 확인\n- 보철에서는 골격 부조화가 크면 **보철만으로 교합을 정상화할 수 없다**는 판단 근거가 된다",
