    variants: "<dl><dt>working</dt><dd>작업측 — 이동 방향 쪽</dd><dt>non-working (balancing)</dt><dd>비작업측 — <b>지렛대 응력, 원칙적으로 제거</b></dd><dt>protrusive</dt><dd>전방운동 시 구치 접촉</dd></dl>",
    distinguish: "- **총의치는 예외** — 균형교합에서는 비작업측 접촉이 안정에 기여하므로 제거 대상이 아니다\n- 자연치·임플란트 보철에서는 **비작업측 간섭이 가장 불리**하다\n- 색을 구분한 교합지(CO 흑/청, 편심 적)로 기록하면 다음 술자가 재현할 수 있다",
