    distinguish: "- **압박 부위와 통증을 느끼는 부위가 다르다** — 이 불일치 자체가 소견\n- **치통 오인의 주범**: 치수 검사가 모두 정상인데 통증이 지속되면 반드시 근육을 촉진\n- **국소마취 감별**: 아픈 치아를 마취해도 통증이 남으면 치성 원인이 아니다\n- 어느 근육에서 어디로 퍼지는지 구체적으로 기재",
