    distinguish: "- **형태로 기술**한다: well-formed / knife-edge / flat / resorbed\n- **하악이 상악보다 빠르다**는 점이 임상 판단의 축 — 하악 유지 대책(임플란트 오버덴처)을 조기에 상담\n- **진행 여부는 이전 모형·사진과 비교**해야 판단할 수 있다\n- 예리한 골융선·이공 노출이 동반되면 완화 설계를 기록",
